import numpy as np, sys, json
from robot import tools, handoff
from ora_lib import current, Point, Direction, object_geometry
from scipy.spatial.transform import Rotation
import pol

ARM="left"
JY=Direction((0.0,1.0,0.0),"world"); JX=Direction((1.0,0.0,0.0),"world")
def opening():
    return current().robot_facts["end_effectors"][ARM]["gripper"]["measured_opening_normalized"]

def goto(cands, label, speed=None, quiet=False):
    for wp in cands:
        x,y,z = wp[:3]; jaw = wp[3] if len(wp)>3 else pol.JAWX
        t=pol.td_target(x,y,z,jaw=jaw)
        kw = {"speed":speed} if speed else {}
        d=tools.move_pose(targets={ARM:t}, dry_run=True, **kw)
        if not d.feasible:
            if not quiet: print(f"  [{label}] infeasible {np.round([x,y,z],3).tolist()} {d.failure_code}")
            continue
        r=tools.move_pose(targets={ARM:t}, **kw)
        p=current().pose(ARM).position
        err=float(p.distance(Point([x,y,z],"world")))
        print(f"  [{label}] -> {np.round([x,y,z],3).tolist()} ok={r.ok} {r.status} err={err:.4f} opening={opening():.3f}")
        return r
    return None

def detect(text, x0,y0, rad=0.06):
    c=tools.vision_ground(camera="head", text=text, max_candidates=3)["result"]["candidates"]
    out=[]
    for cd in c:
        try: g=object_geometry(cd["target_ref"])
        except Exception: continue
        ctr=np.array(g.center_xyz_m)
        if abs(ctr[0]-x0)<rad and abs(ctr[1]-y0)<rad:
            out.append(np.round(ctr,3).tolist())
    return out

if __name__=="__main__":
    cfg=json.loads(sys.argv[1])
    text=cfg["text"]; gx,gy,gz=cfg["grasp"]; px,py,pz=cfg["pre"]
    jawq=cfg.get("jaw")            # [x,y,z] or None
    jaw0 = Direction(jawq,"world") if jawq else JX
    pick_box=cfg["pick_xy"]
    print("start opening", round(opening(),3), "tcp", np.round(current().pose(ARM).position.xyz,3).tolist())
    print("target on table before:", detect(text, *pick_box))
    if opening() < 0.97:
        tools.set_gripper(targets={ARM:"open"})
    r = goto([(px,py,pz,jaw0),(px,py,pz,JY),(px,py,pz,JX)], "pregrasp")
    if r is None: handoff("pregrasp infeasible")
    r = goto([(gx,gy,gz,jaw0),(gx,gy,gz,JY),(gx,gy,gz,JX)], "descend", speed="careful")
    if r is None: handoff("descend infeasible")
    seq=[]
    for i in range(3):
        rg=tools.set_gripper(targets={ARM:"close"}); o=opening(); seq.append(round(o,3))
        print(f"  close{i} {rg.status} opening={o:.3f}")
        if len(seq)>=2 and abs(seq[-1]-seq[-2])<0.005: break
    if opening() > 0.90:
        handoff("gripper never closed on object", seq=seq)
    r = goto([(gx,gy,gz+0.035,jaw0),(gx,gy,gz+0.035,JY),(gx,gy,gz+0.035,JX)], "lift")
    if r is None: handoff("lift infeasible")
    still = detect(text, *pick_box)
    print("after lift, still on table:", still)
    if still:
        handoff("object did not leave the table after lift", still=still, opening=opening())
    # carry
    r = goto([(-0.30,-0.15,1.10,jaw0),(-0.30,-0.15,1.10,JY),(-0.30,-0.16,1.08,JY),(-0.35,-0.15,1.06,JY)], "carry1")
    if r is None or not r.ok: handoff("carry1 failed")
    r = goto([(-0.45,-0.10,1.05,jaw0),(-0.45,-0.10,1.05,JY),(-0.46,-0.10,1.02,JY)], "carry2")
    if r is None or not r.ok: handoff("carry2 failed")
    r = goto([(-0.60,-0.09,0.97,jaw0),(-0.60,-0.09,0.97,JY),(-0.58,-0.09,0.96,JY),(-0.62,-0.09,0.99,JY)], "over-bin")
    if r is None or not r.ok: handoff("over-bin failed", tcp=np.round(current().pose(ARM).position.xyz,3).tolist())
    for i in range(2):
        rg=tools.set_gripper(targets={ARM:"open"}); print("  open", rg.status, round(opening(),3))
    print("after drop, on table:", detect(text, *pick_box))
    r = goto([(-0.55,-0.07,1.05,JY),(-0.50,-0.07,1.06,JY)], "retreat")
    print("DONE", text)
